275	    /**
276	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
277	     * truth for how a telephone is compared and persisted, so inputs that differ only in
278	     * formatting (spaces, dashes, brackets) are treated as the same number.
279	     *
280	     * <p>The rules are:
281	     * <ul>
282	     *   <li>spaces, dashes and brackets are stripped;</li>
283	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
284	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
285	     *       is dropped from the national digits;</li>
286	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
287	     *   <li>for a recognized country code the national number (the digits after the country
288	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
289	     *       digits and {@code '+1'} requires 10.</li>
290	     * </ul>
291	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
292	     * values are returned unchanged.
293	     *
294	     * @param telephone the raw telephone, possibly {@code null}
295	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
296	     *     valid E.164 number
297	     */
298	    public static String normalizeTelephone(String telephone) {
299	        if (telephone == null) {
300	            return null;
301	        }
302	        String trimmed = telephone.trim();
303	        boolean hasCountryCode = trimmed.startsWith("+");
304	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
305	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
306	        if (hasCountryCode) {
307	            stripped = stripped.substring(1);
308	        }
309	        if (!stripped.matches("\\d+")) {
310	            return null;
311	        }
312	        String digits;
313	        if (hasCountryCode) {
314	            digits = stripped;
315	        } else {
316	            if (stripped.startsWith("0")) {
317	                stripped = stripped.substring(1);
318	            }
319	            digits = "61" + stripped;
320	        }
321	        if (digits.length() < 8 || digits.length() > 15) {
322	            return null;
323	        }
324	        if (!hasValidNationalNumberLength(digits)) {
325	            return null;
326	        }
327	        return "+" + digits;
328	    }
329	
330	    /**
331	     * Format a stored E.164 telephone for human display: the country code, a space, then the
332	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
333	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
334	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
335	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
336	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
337	     * kept unchanged elsewhere.
338	     *
339	     * @param telephone the stored E.164 telephone, possibly {@code null}
340	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
341	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
342	     *     unchanged
343	     */
344	    public static String telephoneDisplay(String telephone) {
345	        if (telephone == null) {
346	            return null;
347	        }
348	        if (!telephone.matches("\\+\\d+")) {
349	            return telephone;
350	        }
351	        String digits = telephone.substring(1);
352	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
353	            if (digits.startsWith(countryCode)) {
354	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
355	            }
356	        }
357	        return "+" + groupDigits(digits);
358	    }
359	
360	    /**
361	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
362	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
363	     * {@code "412345678"} becomes {@code "412 345 678"}).
364	     *
365	     * @param digits the national digits
366	     * @return the space-grouped digits
367	     */
368	    private static String groupDigits(String digits) {
369	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
370	        for (int i = 0; i < digits.length(); i++) {
371	            if (i > 0 && i % 3 == 0) {
372	                grouped.append(' ');
373	            }
374	            grouped.append(digits.charAt(i));
375	        }
376	        return grouped.toString();
377	    }
378	
379	    /**
380	     * Required national-number length (the count of digits after the country code) for each
381	     * recognized country code, longest country code first so the prefix match is unambiguous.
382	     */
383	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
384	    static {
385	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
386	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
387	    }
388	
389	    /**
390	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
391	     * length its country code requires. A country code with no registered length places no
392	     * additional constraint and is accepted.
393	     *
394	     * @param digits the E.164 digits without the leading {@code '+'}
395	     * @return {@code true} if the national-number length is valid for the country code
396	     */
397	    private static boolean hasValidNationalNumberLength(String digits) {
398	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
399	            String countryCode = entry.getKey();
400	            if (digits.startsWith(countryCode)) {
401	                return digits.length() - countryCode.length() == entry.getValue();
402	            }
403	        }
404	        return true;
405	    }
