407	    /**
408	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
409	     * upper-cased abbreviation.
410	     */
411	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
412	        "ST", "STREET",
413	        "RD", "ROAD",
414	        "AVE", "AVENUE");
415	
416	    /**
417	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
418	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
419	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
420	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
421	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
422	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
423	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
424	     * value. The transform is idempotent: a normalized address normalizes to itself.
425	     *
426	     * @param address the raw address, possibly {@code null}
427	     * @return the normalized form, or {@code null} if the input was {@code null}
428	     */
429	    public static String normalizeAddress(String address) {
430	        if (address == null) {
431	            return null;
432	        }
433	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
434	        if (collapsed.isEmpty()) {
435	            return collapsed;
436	        }
437	        String[] tokens = collapsed.split(" ");
438	        StringBuilder normalized = new StringBuilder(collapsed.length());
439	        for (int i = 0; i < tokens.length; i++) {
440	            if (i > 0) {
441	                normalized.append(' ');
442	            }
443	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
444	        }
445	        return normalized.toString();
446	    }
