448	    /**
449	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
450	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
451	     * result is that line, with a single space and {@code addressLine2} appended when the second line
452	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
453	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
454	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
455	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
456	     *
457	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
458	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
459	     * @param flatAddress the normalized flat address, possibly {@code null}
460	     * @return the composed address, or the flat value / {@code null} when no structured line is present
461	     */
462	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
463	        if (isPresent(addressLine1)) {
464	            if (isPresent(addressLine2)) {
465	                return addressLine1 + " " + addressLine2;
466	            }
467	            return addressLine1;
468	        }
469	        return flatAddress;
470	    }
