472	    /**
473	     * Whether an address field supplies a usable value, i.e. is non-{@code null} and not blank. This
474	     * is the shared "presence" rule behind both {@link #composeAddress(String, String, String)} and
475	     * {@link #hasAddress(String, String)}, so they agree on what counts as a supplied address field.
476	     *
477	     * @param value the address field, possibly {@code null}
478	     * @return {@code true} if the value is present and non-blank
479	     */
480	    private static boolean isPresent(String value) {
481	        return value != null && !value.isBlank();
482	    }
