484	    /**
485	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
486	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
487	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
488	     *
489	     * @param addressLine1 the structured first line, possibly {@code null}
490	     * @param address the flat address, possibly {@code null}
