497	    /**
498	     * Normalize a household field (such as last name or address) to its canonical form for
499	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
500	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
501	     * that differ only in letter case or spacing are treated as the same value.
502	     *
503	     * @param value the raw field value, possibly {@code null}
504	     * @return the normalized form, or {@code null} if the input was {@code null}
505	     */
506	    public static String normalizeHousehold(String value) {
507	        if (value == null) {
508	            return null;
509	        }
510	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
511	    }
512	
513	    /**
514	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
515	     * last name (compared case-insensitively with collapsed whitespace, see
516	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
517	     * those two fields, so two owners who share a last name and postcode are assigned the same id
518	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
519	     * upper-cased hex characters of the SHA-256 digest of
520	     * {@code normalizedLastName + '|' + postcode}.
521	     *
522	     * @param lastName the owner's last name, possibly {@code null}
523	     * @param postcode the owner's postcode, possibly {@code null}
524	     * @return the household id, or {@code null} if either field is {@code null}
525	     */
526	    public static String householdId(String lastName, String postcode) {
527	        String normalizedLastName = normalizeHousehold(lastName);
528	        if (normalizedLastName == null || postcode == null) {
529	            return null;
530	        }
531	        String key = normalizedLastName + "|" + postcode;
532	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
533	    }
534	
535	    /**
536	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
537	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
538	     * so they all agree on algorithm and encoding.
539	     *
540	     * @param value the string to digest, never {@code null}
541	     * @return the 64-character lower-case hex digest
542	     */
543	    private static String sha256Hex(String value) {
544	        try {
545	            byte[] digest = MessageDigest.getInstance("SHA-256")
546	                .digest(value.getBytes(StandardCharsets.UTF_8));
547	            StringBuilder hex = new StringBuilder(digest.length * 2);
548	            for (byte b : digest) {
549	                hex.append(String.format("%02x", b));
550	            }
551	            return hex.toString();
552	        } catch (NoSuchAlgorithmException e) {
553	            // SHA-256 is a standard algorithm required to be present on every JVM.
554	            throw new IllegalStateException("SHA-256 not available", e);
555	        }
556	    }
557	
558	    /**
559	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
560	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
561	     * <ul>
562	     *   <li>{@code REGION} is the region code derived from the postcode (see
563	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
564	     *       in no known range, and</li>
565	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
566	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
567	     *       name.</li>
568	     * </ul>
569	     * The value is deterministic in the postcode, telephone and last name (e.g.
570	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
571	     *
572	     * @param postcode the owner's postcode, possibly {@code null}
573	     * @param telephone the owner's raw telephone, possibly {@code null}
574	     * @param lastName the owner's last name, possibly {@code null}
575	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
576	     */
577	    public static String customerCode(String postcode, String telephone, String lastName) {
578	        if (telephone == null || lastName == null) {
579	            return null;
580	        }
581	        String region = regionForPostcode(postcode);
582	        if (region == null) {
583	            region = "UNKNOWN";
584	        }
585	        String normalizedTelephone = normalizeTelephone(telephone);
586	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
587	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
588	    }
