590	    /**
591	     * Compute an owner's {@code identityKey}, the single derived value through which all
592	     * duplicate detection is now expressed. It consolidates the three formerly separate
593	     * telephone, email and household duplicate checks into one key, formatted as
594	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
595	     * <ul>
596	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
597	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
598	     *       when no email is present, and</li>
599	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
600	     * </ul>
601	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
602	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
603	     * members of the same household with different telephones have different keys.
604	     *
605	     * @param telephone the owner's raw telephone, possibly {@code null}
606	     * @param email the owner's email, possibly {@code null}
607	     * @param lastName the owner's last name, possibly {@code null}
608	     * @param postcode the owner's postcode, possibly {@code null}
609	     * @return the identity key, never {@code null}
610	     */
611	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
612	        String normalizedTelephone = normalizeTelephone(telephone);
613	        String normalizedEmail = normalizeEmail(email);
614	        String household = householdId(lastName, postcode);
615	        return (normalizedTelephone == null ? "" : normalizedTelephone)
616	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
617	            + "|" + (household == null ? "" : household);
618	    }
