620	    /**
621	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
622	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
623	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
624	     * value is deterministic in those two fields.
625	     *
626	     * @param customerCode the owner's customer code, possibly {@code null}
627	     * @param registrationDate the owner's registration date, possibly {@code null}
628	     * @return the membership number, or {@code null} if either field is {@code null}
629	     */
630	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
631	        if (customerCode == null || registrationDate == null) {
632	            return null;
633	        }
634	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
635	    }
