637	    /**
638	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
639	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
640	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
641	     * and gains 3 when the owner's tenure is more than 365 days (the tenure being the number of days
642	     * from {@code registrationDate} to today). Because a newly created owner has zero tenure, the
643	     * tenure points accrue only once the owner has been a member for over a year.
644	     *
645	     * @param namesakeCount the owner's namesake count, possibly {@code null}
646	     * @param email the owner's email, possibly {@code null}
647	     * @param householdCount the number of members in the owner's household, possibly {@code null}
648	     * @param registrationDate the owner's registration date, possibly {@code null}
649	     * @return the membership points, a non-negative integer
650	     */
651	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
652	            LocalDate registrationDate) {
653	        int points = 0;
654	        if (email != null && !email.isEmpty()) {
655	            points += 2;
656	        }
657	        if (namesakeCount != null && namesakeCount == 0) {
658	            points += 1;
659	        }
660	        if (householdCount != null && householdCount >= 3) {
661	            points += 2;
662	        }
663	        if (registrationDate != null
664	            && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
665	            points += 3;
666	        }
667	        return points;
668	    }
