670	    /**
671	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
672	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
673	     *
674	     * @param membershipPoints the owner's membership points
675	     * @return the membership level, an integer from 1 to 4
676	     */
677	    public static int membershipLevel(int membershipPoints) {
678	        if (membershipPoints >= 6) {
679	            return 4;
680	        }
681	        if (membershipPoints >= 4) {
682	            return 3;
683	        }
684	        if (membershipPoints >= 2) {
685	            return 2;
686	        }
687	        return 1;
688	    }
689	
690	    /**
691	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
692	     * for postcode validation, keyed by the exact city name.
693	     */
694	    private static final Map<String, String> CITY_REGION = Map.of(
695	        "Sydney", "NSW",
696	        "Melbourne", "VIC",
697	        "Brisbane", "QLD");
698	
699	    /**
700	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
701	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
702	     * Because the customer code's region is itself derived from the postcode, the locality now shares
703	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
704	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
705	     *
706	     * @param customerCode the owner's customer code, possibly {@code null}
707	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
708	     */
709	    public static String locality(String customerCode) {
710	        if (customerCode == null) {
711	            return "UNKNOWN";
712	        }
713	        int dash = customerCode.indexOf('-');
714	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
715	    }
716	
717	    /**
718	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
719	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
720	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
721	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
722	     */
723	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
724	        "NSW", "Australia/Sydney",
725	        "VIC", "Australia/Melbourne",
726	        "QLD", "Australia/Brisbane");
727	
728	    /**
729	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
730	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
731	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
732	     * is the owner's {@code locality} (see {@link #locality(String)}), itself the {@code REGION}
733	     * segment of the customer code. A region not in the table (including {@code 'UNKNOWN'}) has no
734	     * timezone and yields {@code null}.
735	     *
736	     * @param customerCode the owner's customer code, possibly {@code null}
737	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
738	     */
739	    public static String timezone(String customerCode) {
740	        return REGION_TIMEZONE.get(locality(customerCode));
741	    }
742	
743	    /**
744	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
745	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
746	     *
747	     * @param city the owner's city, possibly {@code null}
748	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
749	     */
750	    private static String regionForCity(String city) {
751	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
752	    }
753	
754	    /**
755	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
756	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
757	     * inclusive low and high bound of the region's valid 4-digit postcodes
758	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
759	     * table (including {@code 'UNKNOWN'}) places no range constraint.
760	     */
761	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
762	        "NSW", new int[] {2000, 2099},
763	        "VIC", new int[] {3000, 3099},
764	        "QLD", new int[] {4000, 4099});
765	
766	    /**
767	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
768	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
769	     * digits, or one that falls in no known range resolves to {@code null}.
770	     *
771	     * @param postcode the owner's postcode, possibly {@code null}
772	     * @return the matching region, or {@code null} when no range contains the postcode
773	     */
774	    private static String regionForPostcode(String postcode) {
775	        if (postcode == null || !postcode.matches("\\d{4}")) {
776	            return null;
777	        }
778	        int value = Integer.parseInt(postcode);
779	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
780	            int[] range = entry.getValue();
781	            if (value >= range[0] && value <= range[1]) {
782	                return entry.getKey();
783	            }
784	        }
785	        return null;
786	    }
787	
788	    /**
789	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
790	     * {@code null} or empty postcode is always valid. When present it must be exactly four
791	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
792	     * range the value must fall within that inclusive range. A city with no known region accepts
793	     * any four-digit postcode. This is the single source of
794	     * truth for postcode validity, shared by the DTO validation and any persistence path.
795	     *
796	     * @param postcode the owner's postcode, possibly {@code null}
797	     * @param city the owner's city, possibly {@code null}
798	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
799	     */
800	    public static boolean isPostcodeValidForCity(String postcode, String city) {
801	        if (postcode == null || postcode.isEmpty()) {
802	            return true;
803	        }
804	        if (!postcode.matches("\\d{4}")) {
805	            return false;
806	        }
807	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
808	        if (range == null) {
809	            return true;
810	        }
811	        int value = Integer.parseInt(postcode);
812	        return value >= range[0] && value <= range[1];
813	    }
814	
815	    /**
816	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
817	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
818	     * value is deterministic in the customer code and is the standard Luhn check digit: each
819	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
820	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
821	     * brings the weighted sum up to the next multiple of ten.
822	     *
823	     * @param customerCode the owner's customer code, possibly {@code null}
824	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
825	     */
826	    public static Integer checkDigit(String customerCode) {
827	        if (customerCode == null) {
828	            return null;
829	        }
830	        int sum = 0;
831	        boolean dbl = true;
832	        for (int i = customerCode.length() - 1; i >= 0; i--) {
833	            char c = customerCode.charAt(i);
834	            if (c < '0' || c > '9') {
835	                continue;
836	            }
837	            int d = c - '0';
838	            if (dbl) {
839	                d *= 2;
840	                if (d > 9) {
841	                    d -= 9;
842	                }
843	            }
844	            sum += d;
845	            dbl = !dbl;
846	        }
847	        return (10 - (sum % 10)) % 10;
848	    }
849	
850	    /**
851	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
852	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
853	     * is deterministic in the email.
854	     *
855	     * @param email the owner's email, possibly {@code null}
856	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
857	     */
858	    public static String contactPreference(String email) {
859	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
860	    }
861	
862	    /**
863	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
864	     * date. The age in whole years is the number of completed years between {@code birthDate} and
865	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
866	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
867	     * two fields and is only defined when both are present.
868	     *
869	     * @param birthDate the owner's date of birth, possibly {@code null}
870	     * @param registrationDate the owner's registration date, possibly {@code null}
871	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
872	     *     is {@code null}
873	     */
874	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
875	        if (birthDate == null || registrationDate == null) {
876	            return null;
877	        }
878	        int age = Period.between(birthDate, registrationDate).getYears();
879	        if (age < 18) {
880	            return "MINOR";
881	        }
882	        if (age < 65) {
883	            return "ADULT";
884	        }
885	        return "SENIOR";
886	    }
887	
888	    protected Set<Pet> getPetsInternal() {
889	        if (this.pets == null) {
890	            this.pets = new HashSet<>();
891	        }
892	        return this.pets;
893	    }
894	
895	    protected void setPetsInternal(Set<Pet> pets) {
896	        this.pets = pets;
897	    }
898	
899	    public List<Pet> getPets() {
900	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
901	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
902	        return Collections.unmodifiableList(sortedPets);
903	    }
904	
905	    public void setPets(List<Pet> pets) {
906	        this.pets = new HashSet<>(pets);
907	    }
908	
909	    public void addPet(Pet pet) {
910	        getPetsInternal().add(pet);
911	        pet.setOwner(this);
912	    }
913	
914	    /**
915	     * Return the Pet with the given name, or null if none found for this Owner.
916	     *
917	     * @param name to test
918	     * @return true if pet name is already in use
919	     */
920	    public Pet getPet(String name) {
921	        return getPet(name, false);
922	    }
923	
924	    /**
925	     * Return the Pet with the given name, or null if none found for this Owner.
926	     *
927	     * @param name to test
928	     * @return true if pet name is already in use
929	     */
930	    public Pet getPet(String name, boolean ignoreNew) {
931	        name = name.toLowerCase();
932	        for (Pet pet : getPetsInternal()) {
933	            if (!ignoreNew || !pet.isNew()) {
934	                String compName = pet.getName();
935	                compName = compName.toLowerCase();
936	                if (compName.equals(name)) {
937	                    return pet;
938	                }
939	            }
940	        }
941	        return null;
942	    }
943	
944	    public Pet getPet(Integer petId) {
945	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
946	    }
947	
948	    @Override
949	    public String toString() {
950	        return new ToStringCreator(this)
951	
952	            .append("id", this.getId())
953	            .append("new", this.isNew())
954	            .append("lastName", this.getLastName())
955	            .append("firstName", this.getFirstName())
956	            .append("address", this.address)
957	            .append("city", this.city)
958	            .append("telephone", this.telephone)
959	            .toString();
960	    }
961	}
